INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-02' FROM countries WHERE name_en = 'Netherlands';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Voluntary B2B (market-driven Peppol adoption) — B2G mandatory since 2017/2019', 'This deep-dive page reflects publicly available guidance and reporting as of August 2026 and is provided for general awareness, not legal or tax advice. The Dutch cabinet''s position on a domestic B2B mandate was still undecided at time of writing, with a formal direction expected summer 2026 and draft legislation planned for Q4 2026 — confirm current status directly with the Belastingdienst or Logius before building against it.', 'The Netherlands took a market-driven path that most of Europe hasn''t: B2G e-invoicing has been mandatory since 2017, but B2B remains voluntary today, backed by unusually high Peppol adoption. That is now under active review — a March 2026 advisory report recommended a domestic mandate, and the cabinet''s decision is expected imminently, against a firm EU-law floor of July 2030 for cross-border B2B regardless of the outcome.', 'Where B2G exchange happens, it runs on Peppol BIS 3.0 / SI-UBL 2.0 — the same standard voluntarily used by most B2B traffic today, so businesses already exchanging Peppol invoices with government counterparties are largely pre-adapted for whatever the domestic B2B decision brings.', 'Three channels serve B2G traffic today — the Peppol network (recommended), Digipoort (a direct gateway for high-volume suppliers), and the Government Supplier Portal (manual entry for low-volume suppliers) — while B2B exchange happens by mutual agreement, typically also over Peppol.', 'Because B2B is voluntary today, most businesses'' near-term work is about readiness rather than compliance: confirming Peppol capability, watching the cabinet''s scope decision, and preparing for the confirmed 2030 EU cross-border floor regardless of what the domestic mandate ultimately covers.', 'There is no domestic B2B penalty regime today because there is no domestic B2B mandate — but two real pressures already apply: contractual exclusion (counterparties increasingly requiring Peppol to do business at all) and the approaching EU-law floor that applies regardless of the domestic outcome.', 'The Netherlands has run mandatory B2G e-invoicing since 2017 (central government) and 2019 (all public bodies), but B2B remains voluntary — a deliberate market-driven approach with unusually high Peppol adoption. A March 2026 government-commissioned report recommended extending the mandate to domestic B2B on Peppol, phased 2030–2032; the cabinet''s formal decision was expected by summer 2026, with draft legislation planned for Q4 2026. Separately, ViDA''s cross-border B2B e-invoicing and reporting mandate is confirmed EU law from 1 July 2030, regardless of the domestic outcome.', '🌷' FROM countries WHERE name_en = 'Netherlands';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Netherlands';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Voluntary', 'B2B e-invoicing (today)');
